const sectionCopy={field:['A fresh start for your metal.','A little color. A lot of character.','Good people. Good work.'],blueprint:['PURPOSE MEETS PROTECTION.','YOUR PROJECT. YOUR DIRECTION.','LOCALLY MADE CONNECTIONS.'],line:['Protect it.','Make it yours.','Keep it local.'],ledger:['The art of a lasting finish.','Room for something individual.','From our corner of Carolina.'],carbon:['TOUGH WORK.\nTHOUGHTFUL FINISH.','YOUR VISION.\nOUR ATTENTION.','NORTH CAROLINA.\nTHROUGH & THROUGH.'],color:['Good looks.\nHard-working finish.','Find your kind of color.','A local kind of different.'],atlas:['A new path for your metal.','Choose your direction.','Right here in Burlington.'],collage:['START WITH\nTHE GOOD STUFF.','PUT YOUR\nSTAMP ON IT.','FROM HERE.\nFOR YOU.'],brush:['Protection,\napplied with care.','A personal touch.','Close to home.'],orbit:['The first connection.','A world of possibility.','Closer than you think.']};
function star(x,y,r=11){return `<path d="M${x-r} ${y}h${2*r}m-${r}-${r}v${2*r}m-${r*.65}-${r*1.65}l${r*1.3} ${r*1.3}m0-${r*1.3}l-${r*1.3} ${r*1.3}"/>`}
function ornament(type){
 if(type==='blueprint')return '<path d="M24 28H350V260H24ZM12 16h350v256H12M0 140h375M190 0v282"/><circle cx="190" cy="140" r="105"/><path d="M98 70l184 140m0-140L98 210"/>';
 if(type==='orbit')return '<ellipse cx="190" cy="140" rx="166" ry="96" transform="rotate(-22 190 140)"/><ellipse cx="190" cy="140" rx="116" ry="128" transform="rotate(22 190 140)"/><circle cx="190" cy="140" r="66"/><circle cx="39" cy="176" r="7"/><circle cx="298" cy="66" r="5"/>'+star(330,221)+star(61,41,6);
 if(type==='atlas')return Array.from({length:6},(_,i)=>`<path d="M${32-i*7} 148C${10-i*7} ${75-i*7},${109-i*8} ${21-i*6},182 ${41-i*6}S${373+i*5} ${93-i*3},${345+i*5} 172S254 ${262+i*4},158 ${234+i*4}S${61-i*5} 205,${32-i*7} 148Z"/>`).join('');
 if(type==='brush')return '<path class="brush-ring" d="M168 25C27 20 11 174 97 237S329 221 345 125C356 53 249 6 208 28"/><path d="M98 230C151 263 243 265 284 232"/>';
 if(type==='line')return '<path d="M24 203C24 273 168 264 168 192V59C168-2 316 4 316 71V203C316 260 222 260 222 203V71C222 28 76 25 76 87V203"/>';
 if(type==='carbon')return '<circle cx="190" cy="140" r="115"/><circle cx="190" cy="140" r="105" stroke-dasharray="3 9"/><path d="M108 174l75-106 76 106M108 184h150M183 68v116"/>';
 if(type==='color')return '<path class="pigment-shape" d="M79 65C106 0 202 12 225 53S363 68 328 161S219 276 179 230S10 187 79 65Z"/><path d="M132 44C46 110 98 209 187 224S319 165 292 105S195 16 132 44Z"/>';
 if(type==='collage')return '<path d="M54 57L284 21 330 218 86 255Z"/><path d="M82 31L334 68 299 253 52 213Z"/><path stroke-dasharray="5 5" d="M34 273L349 3"/>';
 if(type==='ledger')return '<ellipse cx="190" cy="140" rx="126" ry="105"/><ellipse cx="190" cy="140" rx="117" ry="95"/><path d="M51 140h278M190 22v236"/>'+star(190,140,55);
 return '<path d="M58 158C9 54 235-14 321 69S295 258 161 237S20 185 58 158Z"/><path d="M47 150C22 44 239-8 327 80S288 264 153 231"/>'+star(331,36,14)+star(34,237,9);
}
function formStudy(id){return `<div class="form-study" aria-hidden="true"><svg viewBox="0 0 380 280"><g class="study-lines">${ornament(id)}</g></svg><span class="study-center">N<span> / </span>S</span><span class="study-label mono">SURFACE / POSSIBILITIES</span></div>`}
function boundary(id){const d=id==='blueprint'?'M7 7H493V393H7Z':id==='orbit'?'M248 7C380 0 502 77 490 201S372 391 246 391S2 312 10 199S110 7 248 7Z':id==='collage'?'M12 20L484 8 494 381 4 392Z':id==='color'?'M23 72C54 1 173 10 257 17S470-13 486 75S478 313 458 363S309 391 206 382S-6 414 14 319S-11 145 23 72Z':'M12 37C20 7 171 13 263 9S491 0 490 50S481 312 491 368S345 388 233 391S0 404 9 344S1 73 12 37Z';return `<svg class="island-outline" viewBox="0 0 500 400" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" pathLength="1"/></svg>`}
window.renderConcept=function(c,index){
 document.body.className=`concept-page theme-${c.id}`;document.title=`${String(index+1).padStart(2,'0')} ${c.name} — North State`;
 const copy=sectionCopy[c.id],contactTitle=c.id==='carbon'?'LET’S MAKE\nSOMETHING LAST.':c.id==='line'?'Your next\nchapter.':'Every good finish\nstarts with a conversation.';
 const warm=c.id==='blueprint'?'#eed79b':c.id==='carbon'?'#c8df9e':'#b54f36';
 app.innerHTML=`<svg class="svg-defs" aria-hidden="true"><defs><filter id="ink-wobble"><feTurbulence type="fractalNoise" baseFrequency=".025" numOctaves="2" seed="7" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale="1.6" xChannelSelector="R" yChannelSelector="G"/></filter></defs></svg>
 ${c.id === 'blueprint' ? '<a class="blueprint-refinement-link" href="blueprint.html">Explore 3 monochrome blueprint studies ↗</a>' : ''}<header class="journey-header"><a class="back-link" href="#/">← <span>All concepts</span></a><span class="journey-edition mono">${String(index+1).padStart(2,'0')} / ${c.name}</span></header>
 <a class="traveling-logo" href="#/" aria-label="North State — back to concept collection"><img src="assets/northstate-logo.svg" alt="North State Powder Coating"></a>
 <main class="journey" id="main"><svg class="ink-route" aria-hidden="true"></svg>
 <section class="journey-hero"><div class="hero-kicker mono">Powder coating · Burlington, NC</div><h1>${c.title.replace('\n','<br>')}</h1><p class="hero-description">A fresh perspective on metal.<br>Professional powder coating, with local care.</p><button class="follow-button" data-scroll="services">Follow the line <span aria-hidden="true">↓</span></button><span class="margin-note note-left">a little care<br>goes a long way ${arrow}</span><span class="margin-note note-right">made for<br>what’s next ${arrow}</span><span class="hero-folio mono">${c.id==='blueprint'?'FIG. 01 / THE STARTING POINT':'The story starts here'}</span><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 380 280">${ornament(c.id)}</svg></div></section>
 <div class="islands"><section class="island island-services" id="services" data-step="01">${boundary(c.id)}<span class="island-index mono">01 / The purpose</span><h2>${copy[0].replace('\n','<br>')}</h2><p>Transform and protect your metal with professional powder coating. Custom solutions for industrial equipment and machinery, with protection against corrosion and wear.</p><div class="service-tags"><span>Custom coating</span><span>Protective finishing</span></div><span class="hand-note">care that goes beneath the surface</span></section>
 <section class="island island-color" id="possibilities" data-step="02">${boundary(c.id)}<span class="island-index mono">02 / The possibilities</span><h2>${copy[1].replace('\n','<br>')}</h2>${formStudy(c.id)}<p>Have a project or a finish in mind?<br>Let’s talk about what you’re making.</p><div class="swatch-controls" role="group" aria-label="Try an ink color">${[[warm,'warm'],['#307a93','blue'],['#7b814c','olive'],['#8e5380','violet']].map(([color,name],i)=>`<button class="ink-swatch ${i===0?'active':''}" style="--swatch:${color}" data-color="${color}" aria-label="Try ${name} ink" aria-pressed="${i===0}"></button>`).join('')}<span class="swatch-caption">Change the ink</span></div><span class="palette-note">An interactive concept palette, not a finish catalog.</span><span class="ink-announcement sr-only" aria-live="polite"></span></section>
 <section class="island island-local" id="local" data-step="03">${boundary(c.id)}<span class="island-index mono">03 / The people</span><h2>${copy[2].replace('\n','<br>')}</h2><p>North Carolina based. Personally invested.<br>Quality materials, personal service, and environmentally conscious coating solutions.</p><div class="local-mark"><img src="assets/northstate-wordmark.svg" alt="North State North Carolina"><span class="mono">Burlington, North Carolina</span></div><span class="hand-note">your project is in local hands.</span></section>
 <section class="island island-contact" id="contact" data-step="04">${boundary(c.id)}<span class="island-index mono">04 / Your next step</span><h2>${contactTitle.replace('\n','<br>')}</h2><a class="contact-cta" href="mailto:Jesse@northstatepc.com">Tell us about your project <span aria-hidden="true">↗</span><svg viewBox="0 0 350 20" preserveAspectRatio="none" aria-hidden="true"><path d="M2 12Q124 2 348 10M10 16Q189 10 341 14"/></svg></a><a class="phone" href="tel:+19198012079">(919) 801-2079</a><a class="email" href="mailto:Jesse@northstatepc.com">Jesse@northstatepc.com</a><address>1305 Graham St<br>Burlington, NC</address><span class="hand-note">Let’s give it a new beginning.</span></section></div>
 <footer class="journey-footer"><span class="mono">North State Powder Coating</span><a href="https://northstatepc.com/" target="_blank" rel="noreferrer">Visit the current website ↗</a><span>Concept ${String(index+1).padStart(2,'0')} · ${c.name}</span></footer></main>
 <nav class="concept-dock" aria-label="Concept controls"><a href="#/" class="dock-home" aria-label="All 10 concepts"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M2 2h5v5H2zm11 0h5v5h-5zM2 13h5v5H2zm11 0h5v5h-5z"/></svg><span>Collection</span></a><span class="dock-divider"></span><a class="dock-arrow" href="#/concept/${concepts[(index+9)%10].id}" aria-label="Previous concept">←</a><label class="sr-only" for="concept-select">Choose a concept</label><select id="concept-select">${concepts.map((v,i)=>`<option value="${v.id}" ${v.id===c.id?'selected':''}>${String(i+1).padStart(2,'0')} · ${v.name}</option>`).join('')}</select><a class="dock-arrow" href="#/concept/${concepts[(index+1)%10].id}" aria-label="Next concept">→</a><span class="dock-divider"></span><button class="replay-button" aria-label="Replay the drawing from the top">↺ <span>Replay</span></button><div class="reading-progress" aria-hidden="true"></div></nav>`;
 document.querySelector('#concept-select').addEventListener('change',e=>location.hash=`/concept/${e.target.value}`);
 document.querySelector('[data-scroll]').addEventListener('click',()=>document.querySelector('#services').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'}));
 document.querySelector('.replay-button').addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 document.querySelectorAll('.ink-swatch').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.journey').style.setProperty('--accent',button.dataset.color);document.querySelectorAll('.ink-swatch').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false')});document.querySelector('.ink-announcement').textContent=`${button.getAttribute('aria-label').replace('Try ','')} selected`;}));
 initDrawing(c.id);
};
function initDrawing(id){
 const journey=document.querySelector('.journey'),svg=document.querySelector('.ink-route'),logo=document.querySelector('.traveling-logo'),islands=[...document.querySelectorAll('.island')],hero=document.querySelector('.journey-hero');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let segments=[],frame=0,disposed=false;
 const el=(tag,attrs)=>{const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n};
 function pathFor(a,b,i){const gap=b.y-a.y,mid=(a.y+b.y)/2,w=journey.clientWidth,mobile=w<700,bend=mobile?Math.min(w*.2,75):Math.min(w*.15,210),dir=i%2?1:-1;
  if(id==='blueprint')return `M${a.x},${a.y} V${mid-22} Q${a.x},${mid} ${a.x+22*Math.sign(b.x-a.x||1)},${mid} H${b.x-22*Math.sign(b.x-a.x||1)} Q${b.x},${mid} ${b.x},${mid+22} V${b.y}`;
  if(id==='ledger')return `M${a.x},${a.y} V${a.y+gap*.26} C${a.x},${mid} ${b.x},${mid} ${b.x},${b.y-gap*.26} V${b.y}`;
  if(id==='line')return `M${a.x},${a.y} C${a.x},${a.y+gap*.75} ${b.x},${a.y+gap*.25} ${b.x},${b.y}`;
  if(id==='orbit'){const cx=Math.max(40,Math.min(w-40,(a.x+b.x)/2+dir*bend));return `M${a.x},${a.y} C${cx},${a.y+gap*.1} ${cx},${mid} ${(a.x+b.x)/2},${mid} S${b.x-dir*bend},${b.y-gap*.05} ${b.x},${b.y}`}
  if(id==='color'||id==='carbon'){const cx=Math.max(50,Math.min(w-50,(a.x+b.x)/2+dir*bend));return `M${a.x},${a.y} C${a.x+dir*bend},${a.y+gap*.33} ${cx},${mid+60} ${cx-dir*40},${mid} C${cx-dir*80},${mid-80} ${b.x-dir*bend},${b.y-50} ${b.x},${b.y}`}
  if(id==='collage')return `M${a.x},${a.y} Q${a.x+dir*bend},${a.y+gap*.22} ${(a.x+b.x)/2},${mid} T${b.x},${b.y}`;
  return `M${a.x},${a.y} C${Math.max(25,Math.min(w-25,a.x+dir*bend))},${a.y+gap*.38} ${Math.max(25,Math.min(w-25,b.x-dir*bend))},${b.y-gap*.48} ${b.x},${b.y}`;
 }
 function measure(){if(disposed)return;svg.replaceChildren();segments=[];const base=journey.getBoundingClientRect().top+scrollY;svg.setAttribute('viewBox',`0 0 ${journey.clientWidth} ${journey.clientHeight}`);svg.style.height=`${journey.clientHeight}px`;let a={x:journey.clientWidth/2,y:hero.offsetHeight-52};
  islands.forEach((island,i)=>{const box=island.getBoundingClientRect(),top=box.top+scrollY-base,b={x:box.left+box.width*(i%2?.4:.6),y:top-22},d=pathFor(a,b,i),ghost=el('path',{d,class:'route-ghost'}),path=el('path',{d,class:'route-ink'}),head=el('path',{d:'M-8 -11L0 0L8 -11',class:'route-head'});svg.append(ghost,path,head);const length=path.getTotalLength();path.style.strokeDasharray=length;path.style.strokeDashoffset=length;const samples=Array.from({length:161},(_,j)=>{const p=path.getPointAtLength(length*j/160);return {y:p.y,l:length*j/160}});segments.push({path,head,length,samples,start:a.y,end:b.y});a={x:box.left+box.width*(i%2?.65:.35),y:top+box.height+22};});draw();
 }
 function draw(){frame=0;if(disposed)return;const y=scrollY,w=document.documentElement.clientWidth,mobile=w<700,progress=reduced.matches?1:Math.min(1,y/470),e=progress*progress*(3-2*progress),sizeProgress=reduced.matches?1:Math.min(1,y/130),topProgress=reduced.matches?1:Math.min(1,y/100),startW=mobile?133:165,endW=mobile?80:100,logoW=startW+(endW-startW)*sizeProgress,startX=(w-startW)/2,endX=w-endW-(mobile?20:35);logo.style.width=`${logoW}px`;logo.style.left=`${startX+(endX-startX)*e}px`;logo.style.top=`${(mobile?89:68)+(20-(mobile?89:68))*topProgress}px`;logo.classList.toggle('is-docked',e>.9);
  const target=y+innerHeight*.72;segments.forEach(({path,head,length,start,end})=>{const progress=reduced.matches?1:Math.max(0,Math.min(1,(target-start)/(end-start||1))),drawn=length*progress;path.style.strokeDashoffset=length-drawn;head.style.opacity=drawn>2?'1':'0';const p=path.getPointAtLength(drawn),q=path.getPointAtLength(Math.max(0,drawn-2)),angle=Math.atan2(p.y-q.y,p.x-q.x)*180/Math.PI-90;head.setAttribute('transform',`translate(${p.x},${p.y}) rotate(${angle})`);});
  islands.forEach(island=>island.classList.toggle('is-visible',reduced.matches||island.getBoundingClientRect().top<innerHeight*.86));const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${total>0?Math.min(1,y/total):0})`;
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(draw)}
 const observer=new ResizeObserver(()=>measure());observer.observe(journey);window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',measure);reduced.addEventListener('change',schedule);measure();document.fonts.ready.then(()=>{if(!disposed)measure()});
 window.cleanupConcept=()=>{disposed=true;cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);window.removeEventListener('resize',measure);reduced.removeEventListener('change',schedule);window.cleanupConcept=null;};
}

